?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>AI Settings · Toinky</title><link rel="stylesheet" href="assets/toinky-theme.css"><link rel="stylesheet" href="assets/toinky-admin-shell.css"><link rel="stylesheet" href="assets/toinky-admin-workspace.css"><link rel="stylesheet" href="assets/toinky-responsive.css"><style>body{margin:0;background:#F4EEE2;color:#1C242B;font-family:"Instrument Sans",Arial,sans-serif}.layout{display:grid;grid-template-columns:250px minmax(0,1fr);min-height:100vh}.workspace-main{padding:28px}.panel{background:#fff;border:1px solid #d7d0c4;border-radius:12px;padding:22px;margin-bottom:20px}.field{display:block;margin:14px 0;font-weight:800}.field input{display:block;width:100%;max-width:820px;margin-top:6px;padding:10px;border:1px solid #c9c3b9;border-radius:8px;font:inherit}.btn{border:0;border-radius:7px;background:#B58E46;color:#1C242B;padding:11px 15px;font:800 13px/1 "Instrument Sans",Arial,sans-serif;cursor:pointer}.btn.alt{background:#fff;border:1px solid #6B2938;color:#6B2938}.notice,.error{padding:12px;border-radius:8px;margin-bottom:16px}.notice{background:#dcfce7;color:#166534}.error{background:#fee2e2;color:#991b1b}.diag{width:100%;border-collapse:collapse}.diag th,.diag td{padding:10px;border-bottom:1px solid #e5e1d8;text-align:left;vertical-align:top}.ok{color:#166534;font-weight:800}.bad{color:#991b1b;font-weight:800}.muted{color:#64748b}@media(max-width:800px){.layout{grid-template-columns:1fr}.workspace-main{padding:18px}}</style></head><body><div class="layout admin-app"><?php require_once __DIR__.'/_workspace_sidebar.php';render_workspace_sidebar($admin,'ai_settings',false);?><main class="workspace-main"><header class="workspace-page-header"><div><h1>AI Settings</h1><p>Signed in as <?=e($admin['display_name'])?></p></div></header><p class="muted ai-settings-intro">Manage the shared AI connection used by games, Story Reviews, Inky, and other AI-powered website features.</p><?php if($notice):?><div class="notice"><?=e($notice)?></div><?php endif;?><?php if($error):?><div class="error"><?=e($error)?></div><?php endif;?><section class="panel"><h2>Website-wide AI Connection</h2><form method="post"><input type="hidden" name="csrf_token" value="<?=e(AuthService::csrfToken())?>"><input type="hidden" name="action" value="save_ai_settings"><label class="field">AI Connection URL<input type="url" name="ai_endpoint" required value="<?=e((string)$ai['endpoint'])?>" placeholder="https://endurable-cleft-wildlife.ngrok-free.dev/"></label><label class="field">Model<input name="ai_model" value="<?=e((string)$ai['model'])?>" required></label><label class="field">Timeout (seconds)<input type="number" min="10" max="120" name="ai_timeout_seconds" value="<?=e((string)$ai['timeout_seconds'])?>" required></label><button class="btn" type="submit">Save AI Settings</button></form></section><section class="panel"><h2>Connection Test & Diagnostics</h2><form method="post" style="margin-bottom:16px"><input type="hidden" name="csrf_token" value="<?=e(AuthService::csrfToken())?>"><input type="hidden" name="action" value="test_ai_connection"><button class="btn alt" type="submit">Test Connection</button></form><table class="diag"><tr><th>Check</th><th>Status</th><th>Details</th></tr><?php foreach($diagnostics['checks'] as$check):?><tr><td><?=e($check['label'])?></td><td class="<?=$check['ok']?'ok':'bad'?>"><?=$check['ok']?'Passed':'Needs attention'?></td><td><?=e($check['detail'])?></td></tr><?php endforeach;?></table></section></main></div></body></html>
